package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;

/** Execute the production notebook-attachment job with real writer/export queues. */
public final class NotebookAiNotebookTest {
    public static void main(String[] args)throws Exception {
        String source=new String(Files.readAllBytes(Paths.get("app/src/main/java/org/eink/inkprobe/notebook/NotebookSession.java")),StandardCharsets.UTF_8);
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.io.*;import java.util.*;import java.util.concurrent.*;public class AiNotebookFixture {",
            "static class Context{Context getApplicationContext(){return this;}}static class NotebookPage{final int book,page;NotebookPage(int b,int p){book=b;page=p;}}static class NotebookOutline{static class Entry{}}static class NotebookAiAttachment{static final int MAX_PDF_BYTES=128;final String name;final byte[] data;NotebookAiAttachment(String n,byte[] b){name=n;data=b;}}",
            "interface AiNotebookCallback{void complete(NotebookAiAttachment attachment,IOException error);}interface Source{NotebookPage page(int n)throws IOException;}interface Ink{Object outline(Object stroke);}static class NotebookStrokeRenderer{static Object outline(Object s){return s;}}",
            "static class NotebookPdfEngine{static boolean large;static Runnable afterFirst;static void initialize(Context c){}static void write(OutputStream out,File source,String name,int count,Source pages,Object progress,Ink ink,List<NotebookOutline.Entry> outline)throws IOException{out.write(\"%PDF-1.4\\n\".getBytes(\"UTF-8\"));for(int i=1;i<=count;i++){NotebookPage p=pages.page(i);out.write((p.book+\":\"+p.page+\";\").getBytes(\"UTF-8\"));if(i==1&&afterFirst!=null)afterFirst.run();}if(large)out.write(new byte[200]);out.write(\"%%EOF\".getBytes(\"UTF-8\"));}}",
            "class Document{IOException failure;IOException error(){return failure;}int companionCount(int id)throws IOException{if(id!=2)throw new IOException(\"missing book\");return 3;}File companionSourcePdf(int id){return null;}List<NotebookOutline.Entry> companionOutline(int id){return Collections.emptyList();}NotebookPage companionPage(int id,int n){return new NotebookPage(id,n);}}static class Handler{void post(Runnable r){r.run();}}static class Tasks{final ExecutorService exports=Executors.newSingleThreadExecutor();}final Tasks tasks=new Tasks();final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler();final Document document=new Document();long revision=7;",
            NotebookWorkspaceActivationTest.method(source,"void attachNotebook("),NotebookWorkspaceActivationTest.method(source,"private NotebookPage readAiNotebookPage("),
            "static class Result{NotebookAiAttachment value;IOException error;}Result run(int id,String name)throws Exception{CountDownLatch done=new CountDownLatch(1);Result r=new Result();attachNotebook(new Context(),id,name,(v,e)->{r.value=v;r.error=e;done.countDown();});if(!done.await(10,TimeUnit.SECONDS))throw new AssertionError(\"attachment did not finish\");return r;}void close(){worker.shutdownNow();tasks.exports.shutdownNow();}",
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run()throws Exception{AiNotebookFixture f=new AiNotebookFixture();try{Result ok=f.run(2,\"Quantum\");String pdf=new String(ok.value.data,\"UTF-8\");check(ok.error==null&&ok.value.name.equals(\"Notebook: Quantum\"),\"the selected notebook becomes a named draft attachment\");check(pdf.contains(\"2:1;2:2;2:3;\"),\"every page comes from the requested notebook, in order\");Result missing=f.run(9,\"Missing\");check(missing.value==null&&missing.error!=null,\"missing notebooks do not produce an attachment\");NotebookPdfEngine.large=true;Result large=f.run(2,\"Large\");check(large.value==null&&large.error.getMessage().contains(\"limit\"),\"oversized exports fail without attaching a partial PDF\");NotebookPdfEngine.large=false;NotebookPdfEngine.afterFirst=()->{try{f.worker.submit(()->{f.revision++;}).get();}catch(Exception e){throw new RuntimeException(e);}};Result changed=f.run(2,\"Changing\");check(changed.value==null&&changed.error.getMessage().contains(\"changed\"),\"an edit between page reads rejects a mixed snapshot\");NotebookPdfEngine.afterFirst=null;f.document.failure=new IOException(\"save failed\");Result failed=f.run(2,\"Unsaved\");check(failed.value==null&&failed.error!=null,\"a save failure prevents notebook export\");}finally{NotebookPdfEngine.afterFirst=null;NotebookPdfEngine.large=false;f.close();}System.out.println(\"NotebookAiNotebook: \"+checks+\" assertions passed (whole-book snapshot, source identity, size limits and concurrent edits).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.AiNotebookFixture",fixture);
    }
}
